public static void main(String[] args)
{
    FastReader sc = new FastReader();
    PrintWriter out = new PrintWriter(System.out);
    int n = sc.nextInt();
    int[] arr = new int[2 * n];
    for (int i = 0; i < 2 * n; ++i) arr[i] = sc.nextInt();
    int c = 0;
    Map<Integer, Integer> colorPositions = new HashMap<>();
    for (int i = 0; i < 2 * n; ++i) {
        if (colorPositions.containsKey(arr[i])) {
            if (i - colorPositions.get(arr[i]) == 2) {
                ++c;
            }
        } else {
            colorPositions.put(arr[i], i);
        }
    }
    out.println(c);
    out.flush();
}
